/*
 * Self-destroying service worker.
 *
 * A previous version of this site registered a cache-first service worker at
 * this exact path (/sw.min.js, scope "/"). That old worker kept serving a
 * stale snapshot of the site to returning visitors and would not update on
 * its own. This replacement takes over on the browser's next update check,
 * wipes all caches, unregisters itself, and reloads open pages so they load
 * the live version from the network.
 *
 * It intentionally has NO fetch handler, so it never intercepts requests.
 * Keep this file deployed indefinitely — it is inert for anyone who does not
 * already have the old worker registered.
 */

self.addEventListener('install', () => {
  // Activate immediately instead of waiting for old clients to close.
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // 1. Delete every cache this origin created.
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));

      // 2. Unregister this service worker.
      await self.registration.unregister();

      // 3. Reload all open windows so they fetch the fresh, live site.
      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) {
        client.navigate(client.url);
      }
    })()
  );
});
